package variant5_vehiclerental;

import java.util.Scanner;

// Опис предметної області: Автопрокатна компанія та оренда автотранспорту.
// Завдання коду: Оформлення оренди автомобіля — перевірка стажу водія, розрахунок вартості оренди залежно від класу авто (Economy, Business, SUV), розрахунок страхового поліса (Basic, Full), застави за пальне, формування ваучера оренди, збереження у базу та відправка SMS-підтвердження.

public class Client {
    public int id;
    public String name;
    public int driverExperienceYears;
    public String phone;
}

public class Vehicle {
    public int id;
    public String model;
    public String classType; // "Economy", "Business", "SUV"
    public double dailyRate;
}

public class RentalAgreement {
    public int id;
    public Client client;
    public Vehicle vehicle;
    public int days;
    public String insuranceType; // "Basic", "Full"
    public double rentalTotal;
    public double insuranceTotal;
    public double depositAmount;
    public double finalPrice;
    public String status;
}

public class LegacyRentalManager {
    public void processRentalConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Оформлення оренди автомобіля ===");
        System.out.print("Введіть ім'я клієнта: ");
        String name = scanner.nextLine();
        System.out.print("Введіть клас авто (Economy/Business/SUV): ");
        String carClass = scanner.nextLine();

        Client client = new Client();
        client.id = 15; client.name = name; client.driverExperienceYears = 4; client.phone = "+380673332211";

        Vehicle vehicle = new Vehicle();
        vehicle.id = 505; vehicle.model = "Toyota RAV4"; vehicle.classType = carClass; vehicle.dailyRate = 1800.0;

        RentalAgreement agreement = new RentalAgreement();
        agreement.id = 9012;
        agreement.client = client;
        agreement.vehicle = vehicle;
        agreement.days = 5;
        agreement.insuranceType = "Full";
        agreement.status = "New";

        double rental = agreement.vehicle.dailyRate * agreement.days;
        if ("Business".equalsIgnoreCase(agreement.vehicle.classType)) {
            rental *= 1.3;
        } else if ("SUV".equalsIgnoreCase(agreement.vehicle.classType)) {
            rental *= 1.2;
        }

        double insurance = 0.0;
        if ("Full".equalsIgnoreCase(agreement.insuranceType)) {
            insurance = 500.0 * agreement.days;
        } else if ("Basic".equalsIgnoreCase(agreement.insuranceType)) {
            insurance = 200.0 * agreement.days;
        }

        double deposit = 5000.0;
        if (agreement.client.driverExperienceYears < 3) {
            deposit += 3000.0;
        }

        agreement.rentalTotal = rental;
        agreement.insuranceTotal = insurance;
        agreement.depositAmount = deposit;
        agreement.finalPrice = agreement.rentalTotal + agreement.insuranceTotal;
        agreement.status = "Approved";

        String voucher = "Ваучер оренди #" + agreement.id +
                "\nКлієнт: " + agreement.client.name +
                "\nАвто: " + agreement.vehicle.model +
                "\nОренда: " + agreement.rentalTotal + " грн" +
                "\nСтраховка: " + agreement.insuranceTotal + " грн" +
                "\nЗастава: " + agreement.depositAmount + " грн" +
                "\nЗагалом: " + agreement.finalPrice + " грн";
        System.out.println(voucher);

        System.out.println("[База даних] Ваучер #" + agreement.id + " зафіксовано в системі.");
        System.out.println("[SMS] Підтвердження оренди надіслано на номер " + agreement.client.phone);
    }
}
